module traffic_light
    (
      input rst_n, 
      input clk,
      input pass_request,
      output wire[7:0]clock,
      output reg[2:0]red,
      output reg[2:0]yellow,
      output reg[2:0]green
    );

	parameter idle = 3'd0;
	parameter s1_red = 3'd1;
	parameter s2_yellow = 3'd2;
	parameter s3_green = 3'd3;

	reg[2:0]state;
	reg[7:0]cnt;
	reg p_red,p_green,p_yellow;

	always @(posedge clk or negedge rst_n) begin
		if(!rst_n)begin
			state = idle;
			cnt = 8'd10;
		end
		else case(state)
			s1_red:begin
				if (cnt == 3) 
					state = s3_green;
				else
					state = s1_red;
			end
			s2_yellow:begin
				if (cnt == 3) 
					state = s1_red;
				else
					state = s2_yellow;
			end
			s3_green:begin
				if (cnt == 3) 
					state = s2_yellow;
				else
					state = s3_green;
			end
			default:begin
				state = idle;
			end
		endcase
	end

 	always @(posedge clk or negedge rst_n) begin
		if(!rst_n)begin
			cnt = 8'd10;
		end
		else case(state)
			s1_red:begin
				if (p_green && (cnt > 10) ) 
					cnt = 8'd10;
				else if(!green && p_red)
					cnt = 8'd60;
				else if(!yellow && p_yellow)
					cnt = 8'd5;
				else if(!red && p_red)
					cnt = 8'd10;
				else
					cnt = cnt -1;
			end
			s2_yellow:begin
				if (p_green && (cnt > 10) ) 
					cnt = 8'd10;
				else if(!green && p_red)
					cnt = 8'd60;
				else if(!yellow && p_yellow)
					cnt = 8'd5;
				else if(!red && p_red)
					cnt = 8'd10;
				else
					cnt = cnt -1;
			end
			s3_green:begin
				if (p_green && (cnt > 10) ) 
					cnt = 8'd10;
				else if(!green && p_red)
					cnt = 8'd60;
				else if(!yellow && p_yellow)
					cnt = 8'd5;
				else if(!red && p_red)
					cnt = 8'd10;
				else
					cnt = cnt -1;
			end
			default:begin
				cnt = 8'd10;
			end
		endcase
	end

 	always @(posedge clk or negedge rst_n) begin
		if(!rst_n)begin
			p_red = 1'b0;
			p_green = 1'b0;
			p_yellow = 1'b0;
		end
		else case(state)
			s1_red:begin
				p_red = 1'b1;
				p_green = 1'b0;
				p_yellow = 1'b0;
			end
			s2_yellow:begin
				p_red = 1'b0;
				p_green = 1'b0;
				p_yellow = 1'b1;
			end
			s3_green:begin
				p_red = 1'b0;
				p_green = 1'b1;
				p_yellow = 1'b0;
			end
			default:begin
				p_red = 1'b0;
				p_green = 1'b0;
				p_yellow = 1'b0;
			end
		endcase
	end

 	always @(posedge clk or negedge rst_n) begin
		if(!rst_n)begin
			yellow = 3'b0;
			red = 3'b0;
			green = 3'b0;
		end
		else begin
			yellow = p_yellow;
			red = p_red;
			green = p_green;
		end
	end 

 assign clock = cnt;

endmodule
